    --transition-base: 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    --transition-fast: 0.2s ease;

    container-type: inline-size;
    width: 95%;
    max-width: 580px;
    margin: var(--sp-lg) auto;
    font-family: var(--ff-body);
    color: var(--dc-text);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
