  /* ═══════════════════════════════════════
     2. 折叠面板 + 平缓过渡
     ═══════════════════════════════════════ */
  .dream-details {
    width: 100%;
  }

  .dream-summary {
    display: flex;
    justify-content: center;
    cursor: pointer;
    list-style: none;
    margin-bottom: var(--sp-sm);
    outline: none;
