    background: var(--dc-mat);
    font-family: var(--ff-display);
    font-size: var(--fs-xs);
    letter-spacing: 0.35em;
    color: var(--dc-frame);
    transition: var(--transition-base);
    user-select: none;
  }

  .dream-summary:hover .nameplate {
    background: var(--dc-frame);
    color: var(--dc-mat);
    box-shadow: 0 2px 8px var(--dc-shadow-med);
  }

  .dream-summary:active .nameplate {
    transform: scale(0.97);
  }

  .nameplate-arrow {
    font-size: 10px;
    transition: transform var(--transition-base);
  }

  .dream-details[open] .nameplate-arrow {
    transform: rotate(0deg);
  }

  .dream-details:not([open]) .nameplate-arrow {
    transform: rotate(-90deg);
  }

  /* 折叠过渡容器 */
  .dream-collapse-wrapper {
    display: grid;
    grid-template-rows: 1fr;
    opacity: 1;
    transition: grid-template-rows 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94),
                opacity 0.4s ease;
  }

  .dream-collapse-wrapper.collapsed {
    grid-template-rows: 0fr;
    opacity: 0;
  }

  .dream-collapse-inner {
    overflow: hidden;
  }

  /* ═══════════════════════════════════════
     3. 透视容器 + 画框 + 衬纸 + 画布
     ═══════════════════════════════════════ */
  .dream-perspective {
    perspective: 800px;
    perspective-origin: 50% 40%;
  }

  .dream-frame {
    border: clamp(4px, 1cqw, 6px) solid var(--dc-frame);
    background: var(--dc-frame);
