<script>
  (function () {
    /* ── 1. 心情 ASCII 条渲染 ── */
    const moodValueEl = document.getElementById('dc-mood-value');
    const moodBarEl = document.getElementById('dc-mood-bar');

    if (moodValueEl && moodBarEl) {
      const raw = parseInt(moodValueEl.textContent.trim(), 10);
      const val = isNaN(raw) ? 50 : Math.max(0, Math.min(100, raw));

      /* 总共 20 格 */
      const totalBlocks = 20;
      const filled = Math.round((val / 100) * totalBlocks);
      const empty = totalBlocks - filled;

      /* ██ = 已填充（深灰）  ░░ = 空（浅灰） */
      const filledChar = '█';
      const emptyChar = '░';

      moodBarEl.textContent = filledChar.repeat(filled) + emptyChar.repeat(empty);
    }

    /* ── 2. 鼠标视差效果 ── */
    const canvas = document.getElementById('dc-canvas');
    if (canvas) {
      const frame = canvas.closest('.dream-frame');
      if (frame) {
        const restX = 1.2;
        const restY = -0.8;
        const range = 3.5;

        frame.addEventListener('mousemove', function (e) {
          const rect = frame.getBoundingClientRect();
          const nx = (e.clientX - rect.left) / rect.width - 0.5;
          const ny = (e.clientY - rect.top) / rect.height - 0.5;
          canvas.style.transform =
            'rotateY(' + (nx * range) + 'deg) rotateX(' + (-ny * range) + 'deg)';
        });

        frame.addEventListener('mouseleave', function () {
          canvas.style.transform =
            'rotateY(' + restY + 'deg) rotateX(' + restX + 'deg)';
        });
      }
    }

    /* ── 3. 平缓折叠过渡 ── */
    const details = document.getElementById('dc-details');
    const wrapper = document.getElementById('dc-collapse');

    if (details && wrapper) {
      /* 阻止默认的瞬间切换，改为动画驱动 */
      details.addEventListener('click', function (e) {
        /* 只拦截 summary 的点击 */
        if (!e.target.closest('.dream-summary')) return;
        e.preventDefault();

        if (details.open) {
          /* 正在展开 → 执行关闭动画 */
          wrapper.classList.add('collapsed');
          wrapper.addEventListener('transitionend', function handler() {
            wrapper.removeEventListener('transitionend', handler);
            details.open = false;
          }, { once: true });
        } else {
          /* 正在关闭 → 先打开DOM再执行展开动画 */
          details.open = true;
          wrapper.classList.add('collapsed');
          /* 强制回流后移除 collapsed 触发展开 */
          requestAnimationFrame(function () {
            requestAnimationFrame(function () {
              wrapper.classList.remove('collapsed');
            });
          });
        }
      });
    }
  })();
</script>

